  p=[]
  h=n//100
  if h>1: p.append(O[h])
  if h: p.append('yüz')
  if (n%100)//10: p.append(T[(n%100)//10])
  if n%10: p.append(O[n%10])
  return ' '.join(p)
 def wd(n):
  if n==0: return 'sıfır'
  p=[]
  for v,nm in [(10**9,'milyar'),(10**6,'milyon'),(1000,'bin')]:
   g=n//v
   n=n%v
   if g:
    if not (v==1000 and g==1): p.append(w3(g))
    p.append(nm)
  if n: p.append(w3(n))
  return ' '.join(p)
